describe('File Upload - Maximum File Size Limit', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should reject file upload when file size exceeds 5MB', () => {
    // Create a large file (e.g., 10MB)
    cy.fixture('large-file.zip', {
      binary: true,
      size: 10 * 1024 * 1024
    }).then((file) => {
      cy.get('[data-testid="file-input"]').selectFile(file, { force: true });
    });

    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 413,
      body: {
        error: 'File size exceeds maximum limit of 5MB'
      }
    }).as('fileUploadError');

    // Attempt to submit the form
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the error response
    cy.wait('@fileUploadError');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'File size exceeds maximum limit');

    // Verify file input is cleared
    cy.get('[data-testid="file-input"]').should('have.value', '');

    // Verify retry button is visible
    cy.get('[data-testid="retry-button"]').should('be.visible');
  });

  it('should accept file upload when file size is within 5MB limit', () => {
    // Create a small file (e.g., 2MB)
    cy.fixture('small-file.pdf', {
      binary: true,
      size: 2 * 1024 * 1024
    }).then((file) => {
      cy.get('[data-testid="file-input"]').selectFile(file, { force: true });
    });

    // Intercept the file upload API call
    cy.intercept('POST', '/api/upload', {
      statusCode: 200,
      body: {
        message: 'File uploaded successfully'
      }
    }).as('fileUploadSuccess');

    // Attempt to submit the form
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the success response
    cy.wait('@fileUploadSuccess');

    // Verify success message is displayed
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'File uploaded successfully');

    // Verify file input is cleared
    cy.get('[data-testid="file-input"]').should('have.value', '');

    // Verify retry button is not visible
    cy.get('[data-testid="retry-button"]').should('not.exist');
  });
});
